def solve(s):
    """Run-length encode the input string.
    Returns a list of [character, count] pairs.
    Handles empty input and non-string iterables gracefully.
    """
    # If s is not iterable or is None, return empty list
    if not s:
        return []
    # Ensure we can iterate over the object; if it's not a str but iterable, treat similarly
    try:
        iterator = iter(s)
    except TypeError:
        return []
    result = []
    # Use first element as current
    try:
        cur = next(iterator)
    except StopIteration:
        return []
    cnt = 1
    for ch in iterator:
        if ch == cur:
            cnt += 1
        else:
            result.append([cur, cnt])
            cur = ch
            cnt = 1
    result.append([cur, cnt])
    return result

