def solve(matrix=None):
    """Return the elements of the matrix in clockwise spiral order.
    If matrix is None, read from stdin: first line two ints m n, then m rows of n ints separated by spaces.
    """
    if matrix is None:
        import sys, ast
        data = sys.stdin.read().strip()
        if not data:
            return []
        try:
            matrix = ast.literal_eval(data)
        except Exception:
            # fallback: parse lines
            lines = data.splitlines()
            if not lines:
                return []
            matrix = [list(map(int, line.split())) for line in lines]
    if not matrix:
        return []
    result = []
    top, bottom = 0, len(matrix) - 1
    left, right = 0, len(matrix[0]) - 1
    while top <= bottom and left <= right:
        # traverse top row
        for col in range(left, right + 1):
            result.append(matrix[top][col])
        top += 1
        # traverse right column
        for row in range(top, bottom + 1):
            result.append(matrix[row][right])
        right -= 1
        if top <= bottom:
            # traverse bottom row
            for col in range(right, left - 1, -1):
                result.append(matrix[bottom][col])
            bottom -= 1
        if left <= right:
            # traverse left column
            for row in range(bottom, top - 1, -1):
                result.append(matrix[row][left])
            left += 1
    return result

