def solve(nums=None):
    """Return the length of the longest strictly increasing subsequence.
    If nums is None, read from stdin a Python literal list of integers.
    """
    if nums is None:
        import sys, ast
        data = sys.stdin.read().strip()
        if not data:
            return 0
        nums = ast.literal_eval(data)
    import bisect
    tails = []  # tails[i] is the smallest possible tail of an increasing subsequence of length i+1
    for x in nums:
        # Find index where x can be placed (first >= x)
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)

