def solve(tokens):
    """Evaluate Reverse Polish Notation expression.
    Supports +, -, *, / where division truncates toward zero.
    Handles edge cases: insufficient operands, non-integer tokens, and division by zero
    by returning 0 for the entire expression.
    """
    stack = []
    operators = set('+-*/')
    for tok in tokens:
        if tok in operators:
            # Need two operands
            if len(stack) < 2:
                return 0
            b = stack.pop()
            a = stack.pop()
            if tok == '+':
                res = a + b
            elif tok == '-':
                res = a - b
            elif tok == '*':
                res = a * b
            else:  # division
                if b == 0:
                    return 0
                # Truncate toward zero
                res = int(a / b)
            stack.append(res)
        else:
            try:
                stack.append(int(tok))
            except Exception:
                # Invalid token
                return 0
    return stack[0] if stack else 0

