def solve(nums):
    """Return the length of the longest strictly increasing subsequence.
    Uses O(n log n) patience sorting method.
    """
    if not nums:
        return 0
    import bisect
    tails = []  # tails[i] = smallest possible tail of an IS of length i+1
    for x in nums:
        # find position to insert x in tails (first >= x)
        # Since strictly increasing, we need to replace first element >= x
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)

